656	  /**
657	   * The YARN Router will forward the request to all the YARN RMs in parallel,
658	   * after that it will group all the ApplicationReports by the ApplicationId.
659	   * <p>
660	   * Possible failure:
661	   * <p>
662	   * Client: identical behavior as {@code RMWebServices}.
663	   * <p>
664	   * Router: the Client will timeout and resubmit the request.
665	   * <p>
666	   * ResourceManager: the Router calls each YARN RM in parallel by using one
667	   * thread for each YARN RM. In case a YARN RM fails, a single call will
668	   * timeout. However the Router will merge the ApplicationReports it got, and
669	   * provides a partial list to the client.
670	   * <p>
671	   * State Store: the Router will timeout and it will retry depending on the
672	   * FederationFacade settings - if the failure happened before the select
673	   * operation.
674	   */
675	  @Override
676	  public AppsInfo getApps(HttpServletRequest hsr, String stateQuery,
677	      Set<String> statesQuery, String finalStatusQuery, String userQuery,
678	      String queueQuery, String count, String startedBegin, String startedEnd,
679	      String finishBegin, String finishEnd, Set<String> applicationTypes,
680	      Set<String> applicationTags, String name, Set<String> unselectedFields) {
681	    AppsInfo apps = new AppsInfo();
682	    long startTime = clock.getTime();
683	
684	    Map<SubClusterId, SubClusterInfo> subClustersActive = null;
685	    try {
686	      subClustersActive = federationFacade.getSubClusters(true);
687	    } catch (YarnException e) {
688	      routerMetrics.incrMultipleAppsFailedRetrieved();
689	      return null;
690	    }
691	
692	    // Send the requests in parallel
693	    CompletionService<AppsInfo> compSvc =
694	        new ExecutorCompletionService<>(this.threadpool);
695	
696	    // HttpServletRequest does not work with ExecutorCompletionService.
697	    // Create a duplicate hsr.
698	    final HttpServletRequest hsrCopy = clone(hsr);
699	    for (final SubClusterInfo info : subClustersActive.values()) {
700	      compSvc.submit(new Callable<AppsInfo>() {
701	        @Override
702	        public AppsInfo call() {
703	          DefaultRequestInterceptorREST interceptor =
704	              getOrCreateInterceptorForSubCluster(
705	                  info.getSubClusterId(), info.getRMWebServiceAddress());
706	          AppsInfo rmApps = interceptor.getApps(hsrCopy, stateQuery,
707	              statesQuery, finalStatusQuery, userQuery, queueQuery, count,
708	              startedBegin, startedEnd, finishBegin, finishEnd,
709	              applicationTypes, applicationTags, name, unselectedFields);
710	
711	          if (rmApps == null) {
712	            routerMetrics.incrMultipleAppsFailedRetrieved();
713	            LOG.error("Subcluster {} failed to return appReport.",
714	                info.getSubClusterId());
715	            return null;
716	          }
717	          return rmApps;
718	        }
719	      });
720	    }
721	
722	    // Collect all the responses in parallel
723	    for (int i = 0; i < subClustersActive.size(); i++) {
724	      try {
725	        Future<AppsInfo> future = compSvc.take();
726	        AppsInfo appsResponse = future.get();
727	
728	        long stopTime = clock.getTime();
729	        routerMetrics.succeededMultipleAppsRetrieved(stopTime - startTime);
730	
731	        if (appsResponse != null) {
732	          apps.addAll(appsResponse.getApps());
733	        }
734	      } catch (Throwable e) {
735	        routerMetrics.incrMultipleAppsFailedRetrieved();
736	        LOG.warn("Failed to get application report", e);
737	      }
738	    }
739	
740	    if (apps.getApps().isEmpty()) {
741	      return null;
742	    }
743	
744	    // Merge all the application reports got from all the available YARN RMs
745	    return RouterWebServiceUtil.mergeAppsInfo(
746	        apps.getApps(), returnPartialReport);
747	  }
