749	  /**
750	   * Get a copy of a HTTP request. This is for thread safety.
751	   * @param hsr HTTP servlet request to copy.
752	   * @return Copy of the HTTP request.
753	   */
754	  private HttpServletRequestWrapper clone(final HttpServletRequest hsr) {
755	    if (hsr == null) {
756	      return null;
757	    }
758	    @SuppressWarnings("unchecked")
759	    final Map<String, String[]> parameterMap =
760	        (Map<String, String[]>) hsr.getParameterMap();
761	    final String pathInfo = hsr.getPathInfo();
762	    final String user = hsr.getRemoteUser();
763	    final Principal principal = hsr.getUserPrincipal();
764	    final String mediaType =
765	        RouterWebServiceUtil.getMediaTypeFromHttpServletRequest(
766	            hsr, AppsInfo.class);
767	    return new HttpServletRequestWrapper(hsr) {
768	        public Map<String, String[]> getParameterMap() {
769	          return parameterMap;
770	        }
771	        public String getPathInfo() {
772	          return pathInfo;
773	        }
774	        public String getRemoteUser() {
775	          return user;
776	        }
777	        public Principal getUserPrincipal() {
778	          return principal;
779	        }
780	        public String getHeader(String value) {
781	          // we override only Accept
782	          if (value.equals(HttpHeaders.ACCEPT)) {
783	            return mediaType;
784	          }
785	          return null;
786	        }
787	      };
788	  }
