804	  /**
805	   * The YARN Router will forward to the request to all the SubClusters to find
806	   * where the node is running.
807	   * <p>
808	   * Possible failure:
809	   * <p>
810	   * Client: identical behavior as {@code RMWebServices}.
811	   * <p>
812	   * Router: the Client will timeout and resubmit the request.
813	   * <p>
814	   * ResourceManager: the Router will timeout and the call will fail.
815	   * <p>
816	   * State Store: the Router will timeout and it will retry depending on the
817	   * FederationFacade settings - if the failure happened before the select
818	   * operation.
819	   */
820	  @Override
821	  public NodeInfo getNode(String nodeId) {
822	    final Map<SubClusterId, SubClusterInfo> subClustersActive =
823	        getActiveSubclusters();
824	    if (subClustersActive.isEmpty()) {
825	      throw new NotFoundException(
826	          FederationPolicyUtils.NO_ACTIVE_SUBCLUSTER_AVAILABLE);
827	    }
828	    final Map<SubClusterInfo, NodeInfo> results =
829	        getNode(subClustersActive.values(), nodeId);
830	
831	    // Collect the responses
832	    NodeInfo nodeInfo = null;
833	    for (NodeInfo nodeResponse : results.values()) {
834	      try {
835	        // Check if the node was already found in a different SubCluster and
836	        // it has an old health report
837	        if (nodeInfo == null || nodeInfo.getLastHealthUpdate() <
838	            nodeResponse.getLastHealthUpdate()) {
839	          nodeInfo = nodeResponse;
840	        }
841	      } catch (Throwable e) {
842	        LOG.warn("Failed to get node report ", e);
843	      }
844	    }
845	
846	    if (nodeInfo == null) {
847	      throw new NotFoundException("nodeId, " + nodeId + ", is not found");
848	    }
849	    return nodeInfo;
850	  }
