852	  /**
853	   * Get a node and the subcluster where it is.
854	   * @param subClusters Subclusters where to search.
855	   * @param nodeId Identifier of the node we are looking for.
856	   * @return Map between subcluster and node.
857	   */
858	  private Map<SubClusterInfo, NodeInfo> getNode(
859	      Collection<SubClusterInfo> subClusters, String nodeId) {
860	
861	    // Send the requests in parallel
862	    CompletionService<NodeInfo> compSvc =
863	        new ExecutorCompletionService<NodeInfo>(this.threadpool);
864	    final Map<SubClusterInfo, Future<NodeInfo>> futures = new HashMap<>();
865	    for (final SubClusterInfo subcluster : subClusters) {
866	      final SubClusterId subclusterId = subcluster.getSubClusterId();
867	      Future<NodeInfo> result = compSvc.submit(() -> {
868	        try {
869	          DefaultRequestInterceptorREST interceptor =
870	              getOrCreateInterceptorForSubCluster(
871	                  subclusterId, subcluster.getRMWebServiceAddress());
872	          return interceptor.getNode(nodeId);
873	        } catch (Exception e) {
874	          LOG.error("Subcluster {} failed to return nodeInfo.",
875	              subclusterId);
876	          return null;
877	        }
878	      });
879	      futures.put(subcluster, result);
880	    }
881	
882	    // Collect the results
883	    final Map<SubClusterInfo, NodeInfo> results = new HashMap<>();
884	    for (Entry<SubClusterInfo, Future<NodeInfo>> entry : futures.entrySet()) {
885	      try {
886	        final Future<NodeInfo> future = entry.getValue();
887	        final NodeInfo nodeInfo = future.get();
888	        // Check if the node was found in this SubCluster
889	        if (nodeInfo != null) {
890	          SubClusterInfo subcluster = entry.getKey();
891	          results.put(subcluster, nodeInfo);
892	        }
893	      } catch (Throwable e) {
894	        LOG.warn("Failed to get node report ", e);
895	      }
896	    }
897	
898	    return results;
899	  }
