913	        getNode(subClusters, nodeId);
914	    SubClusterInfo subcluster = null;
915	    NodeInfo nodeInfo = null;
916	    for (Entry<SubClusterInfo, NodeInfo> entry : results.entrySet()) {
917	      NodeInfo nodeResponse = entry.getValue();
918	      if (nodeInfo == null || nodeInfo.getLastHealthUpdate() <
919	          nodeResponse.getLastHealthUpdate()) {
920	        subcluster = entry.getKey();
921	        nodeInfo = nodeResponse;
922	      }
923	    }
924	    if (subcluster == null) {
925	      throw new NotFoundException(
926	          "Cannot find " + nodeId + " in any subcluster");
927	    }
928	    return subcluster;
929	  }
