950	  @Override
951	  public NodesInfo getNodes(String states) {
952	
953	    NodesInfo nodes = new NodesInfo();
954	
955	    final Map<SubClusterId, SubClusterInfo> subClustersActive;
956	    try {
957	      subClustersActive = getActiveSubclusters();
958	    } catch (Exception e) {
959	      LOG.error("Cannot get nodes: {}", e.getMessage());
960	      return new NodesInfo();
961	    }
962	
963	    // Send the requests in parallel
964	    CompletionService<NodesInfo> compSvc =
965	        new ExecutorCompletionService<NodesInfo>(this.threadpool);
966	
967	    for (final SubClusterInfo info : subClustersActive.values()) {
968	      compSvc.submit(new Callable<NodesInfo>() {
969	        @Override
970	        public NodesInfo call() {
971	          DefaultRequestInterceptorREST interceptor =
972	              getOrCreateInterceptorForSubCluster(
973	                  info.getSubClusterId(), info.getRMWebServiceAddress());
974	          try {
975	            NodesInfo nodesInfo = interceptor.getNodes(states);
976	            return nodesInfo;
977	          } catch (Exception e) {
978	            LOG.error("Subcluster {} failed to return nodesInfo.",
979	                info.getSubClusterId());
980	            return null;
981	          }
982	        }
983	      });
984	    }
985	
986	    // Collect all the responses in parallel
987	
988	    for (int i = 0; i < subClustersActive.size(); i++) {
989	      try {
990	        Future<NodesInfo> future = compSvc.take();
991	        NodesInfo nodesResponse = future.get();
992	
993	        if (nodesResponse != null) {
994	          nodes.addAll(nodesResponse.getNodes());
995	        }
996	      } catch (Throwable e) {
997	        LOG.warn("Failed to get nodes report ", e);
998	      }
999	    }
1000	
1001	    // Delete duplicate from all the node reports got from all the available
1002	    // YARN RMs. Nodes can be moved from one subclusters to another. In this
1003	    // operation they result LOST/RUNNING in the previous SubCluster and
1004	    // NEW/RUNNING in the new one.
1005	
1006	    return RouterWebServiceUtil.deleteDuplicateNodesInfo(nodes.getNodes());
1007	  }
